for r in range(14,18):
 seq=T[r,3:].tolist(); best=[]; mmax=0
 for i in range(30):
  for j in range(30):
   m=0
   while m<len(seq) and i+m<30 and j+m<30 and T[i+m,j+m]==seq[m]:m+=1
